<?php
declare(strict_types=1);
ini_set('display_errors','0');
header('Content-Type: application/json; charset=utf-8');
header('Cache-Control: no-store');
header('X-Content-Type-Options: nosniff');
const MAX_TARGETS=20; const MAX_PORTS=30; const TIMEOUT=1.2;
$services=[20=>'FTP Data',21=>'FTP Control',22=>'SSH',23=>'Telnet',25=>'SMTP',53=>'DNS (TCP)',80=>'HTTP',110=>'POP3',123=>'NTP (TCP)',135=>'MS RPC',139=>'NetBIOS',143=>'IMAP',161=>'SNMP (TCP)',389=>'LDAP',443=>'HTTPS',445=>'SMB',465=>'SMTPS',502=>'Modbus TCP',587=>'SMTP Submission',636=>'LDAPS',993=>'IMAPS',995=>'POP3S',1433=>'Microsoft SQL Server',1521=>'Oracle',1883=>'MQTT',3306=>'MySQL',3389=>'RDP',4840=>'OPC UA',5432=>'PostgreSQL',5900=>'VNC',8080=>'HTTP Alternate',8443=>'HTTPS Alternate',8883=>'MQTT TLS'];
$presets=['common'=>['label'=>'Common','ports'=>[22,53,80,443,445,3389]],'web'=>['label'=>'Web','ports'=>[80,443,8080,8443]],'remote'=>['label'=>'Remote access','ports'=>[22,23,3389,5900]],'windows'=>['label'=>'Windows','ports'=>[135,139,445,3389]],'database'=>['label'=>'Databases','ports'=>[1433,1521,3306,5432]],'industrial'=>['label'=>'Industrial / IoT','ports'=>[502,1883,4840,8883]]];
function out(int $status,array $data):never{http_response_code($status);echo json_encode($data,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE);exit;}
function targets(mixed $v):array{if(is_string($v))$v=preg_split('/[\s,;]+/',trim($v),-1,PREG_SPLIT_NO_EMPTY);if(!is_array($v))out(422,['ok'=>false,'error'=>'Enter at least one IPv4 address.']);$r=[];foreach($v as $x){$x=trim((string)$x);if(filter_var($x,FILTER_VALIDATE_IP,FILTER_FLAG_IPV4)===false)out(422,['ok'=>false,'error'=>"Invalid IPv4 address: $x"]);$r[$x]=$x;}if(!$r)out(422,['ok'=>false,'error'=>'Enter at least one IPv4 address.']);if(count($r)>MAX_TARGETS)out(422,['ok'=>false,'error'=>'Maximum '.MAX_TARGETS.' targets.']);return array_values($r);}
function ports(mixed $v,array $services):array{if(!is_array($v)||!$v)out(422,['ok'=>false,'error'=>'Select at least one port.']);$r=[];foreach($v as $x){if(is_int($x))$p=$x;elseif(is_string($x)&&ctype_digit($x))$p=(int)$x;else out(422,['ok'=>false,'error'=>'Invalid port.']);if(!isset($services[$p]))out(422,['ok'=>false,'error'=>"Port $p is not available."]);$r[$p]=$p;}if(count($r)>MAX_PORTS)out(422,['ok'=>false,'error'=>'Maximum '.MAX_PORTS.' ports.']);sort($r);return array_values($r);}
function check(string $ip,int $port,string $service):array{$t=hrtime(true);$errno=0;$err='';set_error_handler(static fn()=>true);$s=fsockopen($ip,$port,$errno,$err,TIMEOUT);restore_error_handler();$ms=round((hrtime(true)-$t)/1e6,1);if(is_resource($s)){fclose($s);return ['port'=>$port,'service'=>$service,'status'=>'open','ms'=>$ms,'message'=>'TCP connection established'];}return ['port'=>$port,'service'=>$service,'status'=>'no_connection','ms'=>$ms,'message'=>'Closed, filtered, unreachable, or timed out'];}
if(($_SERVER['REQUEST_METHOD']??'GET')==='GET')out(200,['ok'=>true,'services'=>$services,'presets'=>$presets,'limits'=>['targets'=>MAX_TARGETS,'ports'=>MAX_PORTS]]);
if($_SERVER['REQUEST_METHOD']!=='POST')out(405,['ok'=>false,'error'=>'Method not allowed.']);if(!str_starts_with(strtolower($_SERVER['CONTENT_TYPE']??''),'application/json'))out(415,['ok'=>false,'error'=>'JSON required.']);$raw=file_get_contents('php://input');if(!is_string($raw)||strlen($raw)>32768)out(400,['ok'=>false,'error'=>'Invalid request.']);try{$body=json_decode($raw,true,32,JSON_THROW_ON_ERROR);}catch(JsonException){out(400,['ok'=>false,'error'=>'Invalid JSON.']);}$ips=targets($body['targets']??null);$ps=ports($body['ports']??null,$services);$start=hrtime(true);$groups=[];$open=0;$failed=0;foreach($ips as $ip){$items=[];foreach($ps as $p){$r=check($ip,$p,$services[$p]);$items[]=$r;$r['status']==='open'?$open++:$failed++;}$groups[]=['ip'=>$ip,'ports'=>$items];}out(200,['ok'=>true,'protocol'=>'TCP','summary'=>['targets'=>count($ips),'checks'=>count($ips)*count($ps),'open'=>$open,'noConnection'=>$failed,'durationMs'=>round((hrtime(true)-$start)/1e6,1)],'results'=>$groups,'timestamp'=>date(DATE_ATOM)]);
